<template><div class="login-bg"><div class="logo">📱</div><h1>彩美特小程序</h1><p class="sub">企业服务一站式平台</p><div class="card"><h2>登录 / 注册</h2><div class="form"><label>手机号</label><input v-model="phone" type="tel" maxlength="11" placeholder="请输入手机号" /><label>验证码</label><div class="code-row"><input v-model="code" maxlength="6" placeholder="6 位验证码" /><button :disabled="sending || countdown > 0" @click="sendCode">{{ countdown > 0 ? `${countdown}s` : '发送验证码' }}</button></div><button class="login-btn" :disabled="loading || !phone || !code" @click="login">{{ loading ? '登录中...' : '登录' }}</button></div><div class="demo"><p>🎯 演示模式 - 一键登录</p><button v-for="d in demos" :key="d.label" @click="quick(d)">{{ d.label }}</button></div></div><p class="terms">登录即同意 <span>用户协议</span> 和 <span>隐私政策</span></p></div></template>
<script setup>import { ref } from 'vue'; import { useRouter } from 'vue-router'; const router = useRouter(); const phone = ref(''); const code = ref(''); const loading = ref(false); const sending = ref(false); const countdown = ref(0); const demos = [{ label: '👤 个人会员', phone: '13800138001' }, { label: '🏢 企业用户', phone: '18676970008' }]; async function sendCode() { if (!phone.value) return uni.showToast({ title: '请输入手机号', icon: 'none' }); sending.value = true; countdown.value = 60; const t = setInterval(() => { countdown.value--; if (countdown.value <= 0) { clearInterval(t); sending.value = false } }, 1000); uni.showToast({ title: '验证码已发送（演示）', icon: 'success' }) } async function login() { loading.value = true; try { uni.setStorageSync('caimeite_token', 'minip_demo_' + Date.now()); uni.setStorageSync('caimeite_user', JSON.stringify({ id: 1, name: '小程序用户', phone: phone.value, role: 'member' })); uni.showToast({ title: '登录成功', icon: 'success' }); setTimeout(() => router.push('/minip/me'), 500) } catch { uni.showToast({ title: '登录失败', icon: 'none' }) } finally { loading.value = false } } function quick(d) { phone.value = d.phone; code.value = '888888'; login() } </script>
<style scoped>.login-bg { min-height: 100vh; background: linear-gradient(135deg, #6366f1, #8b5cf6); padding: 40px 20px; display: flex; flex-direction: column; align-items: center; font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif; color: #fff; max-width: 480px; margin: 0 auto; } .logo { font-size: 56px; margin-bottom: 8px; } h1 { font-size: 22px; font-weight: 700; margin: 0; } .sub { font-size: 13px; opacity: 0.85; margin: 4px 0 24px; } .card { background: #fff; color: #1f2329; border-radius: 16px; padding: 20px; width: 100%; box-shadow: 0 8px 24px rgba(0,0,0,0.15); } .card h2 { font-size: 16px; text-align: center; margin: 0 0 16px; } .form label { display: block; font-size: 12px; color: #6b7280; margin: 8px 0 4px; } .form input { width: 100%; padding: 12px; border: 1px solid #e5e7eb; border-radius: 8px; font-size: 14px; box-sizing: border-box; } .form input:focus { outline: none; border-color: #6366f1; } .code-row { display: flex; gap: 8px; } .code-row input { flex: 1; } .code-row button { padding: 12px 14px; background: #eef2ff; color: #6366f1; border: 0; border-radius: 8px; font-size: 12px; cursor: pointer; white-space: nowrap; } .login-btn { width: 100%; background: linear-gradient(135deg, #6366f1, #8b5cf6); color: #fff; border: 0; border-radius: 8px; padding: 12px; font-size: 14px; font-weight: 600; margin-top: 16px; cursor: pointer; } .login-btn:disabled { opacity: 0.5; } .demo { margin-top: 16px; padding-top: 16px; border-top: 1px solid #f3f4f6; } .demo p { font-size: 11px; color: #9ca3af; text-align: center; margin: 0 0 8px; } .demo button { width: 100%; padding: 10px; background: #f9fafb; border: 0; border-radius: 8px; margin-bottom: 6px; font-size: 13px; cursor: pointer; } .terms { font-size: 11px; margin-top: 16px; opacity: 0.85; text-align: center; } .terms span { text-decoration: underline; }</style>